import json,os,time
R="/workspace/nox/web/site/qa/rework/"
N={
"music":["Ручной просмотр S5, 02:50. Spotify: каркас похож (сайдбар, шапка плейлиста, плеер), но все 5 карточек «Альбомы» пустые заглушки без названий и обложек, плейлист пуст. Как у Spotify: подпись под каждой карточкой (название/исполнитель), при пустой библиотеке показывать реальные созданные треки ACE-Step или скрыть секцию.","Плавающий чип «МУЗЫКА / МУЗЫКА» справа внизу дублирует название и перекрывает ползунок громкости плеера: убрать дубль или сместить выше.","Волна wavesurfer не видна на экране (прогресс-бар обычный): при воспроизведении показать волну как в SoundCloud/Spotify Canvas."],
"studio":["Ручной просмотр S5, 02:50. Midjourney/Krea: на 1440x900 нижняя панель ввода («Создать») перекрыта круглой кнопкой мини-чата справа и плотно прижата к нижней панели, кнопка обрезана. Поднять строку промпта выше или убрать мини-чат на этой странице.","Мозаика пустых тёмных плиток с чёрным солнцем посередине выглядит как пустой экран: как у Midjourney — masonry-лента прежних работ (Muuri/Masonry) с реальными превью; пока их нет — одна понятная пустая карточка «Опишите кадр».","Заголовок «Фотостудия» и надпись про отключение генерации слиплись с шапкой; плашка статуса мелким моно-шрифтом, оформить как Shoelace alert."],
"photo":["Ручной просмотр S5, 02:50. Filerobot-редактор подключён (хорошо), но холст с белой рамкой вокруг тёмного артборда выглядит как вставка из другого продукта: белый фон холста заменить на тёмное стекло, как в Photopea/Krea.","Нижняя часть холста и панель «ИИ-обработка холста» заходят под нижнюю панель: на 1440x900 не видны кнопки «Описать фото» и дальше, нужна прокрутка/уменьшение холста.","Правая панель «Диалог с NOX / Генерация / ИИ-обработка» свёрстана вручную разнородными кнопками: привести к одному стилю Shoelace (button, select, textarea), единые размеры."]}
for k,v in N.items():
    f=R+k+".json"
    j=json.load(open(f)) if os.path.exists(f) else {"page":k+".html","cycle":0,"fails":[]}
    j["s5_review"]={"ts":time.strftime("%F %T"),"notes":v}
    j["fails"]=[x for x in j.get("fails",[]) if not str(x.get("item","")).startswith("РУЧНОЙ")]+[{"item":"РУЧНОЙ ПРОСМОТР S5 (приоритетнее авто-замечаний)","detail":v}]
    json.dump(j,open(f,"w"),ensure_ascii=False,indent=1)
print("ok")
